"""Atari 8-bit memory snapshots (.xlm): walk the ANTIC display list."""
import struct

# Scan lines generated by one mode instruction.
LINES = {
    2: 8,
    3: 10,
    4: 8,
    5: 16,
    6: 8,
    7: 16,
    8: 8,
    9: 4,
    10: 4,
    11: 2,
    12: 1,
    13: 2,
    14: 1,
    15: 1,
}

# Bytes fetched by a normal-width mode instruction.
WIDTH = {
    2: 40,
    3: 40,
    4: 40,
    5: 40,
    6: 20,
    7: 20,
    8: 10,
    9: 10,
    10: 20,
    11: 20,
    12: 20,
    13: 40,
    14: 40,
    15: 40,
}
LIMIT = 2000


class DisplayListError(ValueError):
    pass


def parse(data):
    if len(data) != 9 + 65536 or data[:6] != b"XLMEM\x00":
        raise DisplayListError("not a memory snapshot")
    pc, dmactl = struct.unpack_from("<HB", data, 6)
    mem = data[9:]
    if (dmactl & 3) == 0:
        raise DisplayListError("playfield DMA is off")

    def fetch():
        nonlocal pc
        b = mem[pc]
        pc = (pc + 1) & 0xFFFF
        return b

    pf_width = dmactl & 3
    scan = mode_lines = blank_lines = dli = lms_count = jumps = screen = 0
    msc = 0
    modes = {}
    ranges = []
    for _ in range(LIMIT):
        op = fetch()
        if op & 0x80:
            dli += 1
        low = op & 15
        if low == 0:
            n = ((op >> 4) & 7) + 1
            scan += n
            blank_lines += n
            continue
        if low == 1:
            target = fetch() | fetch() << 8
            jumps += 1
            if op & 0x40:
                # JVB ends the frame; a plain JMP continues at its operand.
                break
            pc = target
            continue
        if low not in LINES or low not in WIDTH:
            raise DisplayListError("unsupported mode %X" % low)
        if op & 0x40:
            msc = fetch() | fetch() << 8
            lms_count += 1
        n = WIDTH[low]
        if pf_width == 1:
            # 128 color clocks versus 160 in a normal playfield.
            n = n * 4 // 5
        elif pf_width == 3:
            # 192 color clocks versus 160 in a normal playfield.
            n = n * 6 // 5
        if op & 0x10:
            # HSCROL makes ANTIC fetch one extra boundary byte.
            n += 1
        start = msc
        msc = (msc + n) & 0xFFFF
        if ranges and ranges[-1][1] == start:
            ranges[-1][1] = msc
        else:
            ranges.append([start, msc])
        screen += n
        mode_lines += 1
        scan += LINES[low]
        modes[low] = modes.get(low, 0) + 1
    else:
        raise DisplayListError("display list never reaches a JVB")
    return {"scanlines": scan, "mode_lines": mode_lines, "blank_lines": blank_lines, "dli": dli,
            "lms": lms_count, "jumps": jumps, "screen_bytes": screen,
            "modes": {"%X" % m: modes[m] for m in sorted(modes)},
            "fetch": ["%04x-%04x" % (a, b) for a, b in ranges]}
